protected override void OnModelCreating(ModelBuilder modelBuilder)
{
    // HasIndex removed: Cosmos DB indexing is managed via the container's
    // indexing policy (Azure Portal / Bicep / Terraform), not EF Core.
    // In EF Core 9 HasIndex throws InvalidOperationException for Cosmos entities.

    modelBuilder.Entity<Product>().ToContainer("Products");

    // EF Core 9 changed the default discriminator property from "Discriminator"
    // to "$type". Our existing 500K documents use "Discriminator", and direct
    // SQL queries reference c.Discriminator — keep the old name.
    modelBuilder.Entity<Product>().HasDiscriminator<string>("Discriminator");

    // EF Core 9 changed id values from "EntityType|Key" (e.g. "Product|123")
    // to just the key value ("123"). Preserve the old compound format so
    // FindAsync and point-reads continue to work against existing documents.
    modelBuilder.Entity<Product>().HasRootDiscriminatorInJsonId(true);
}

