2. class ProductContext : DbContext
3. {
4.     public DbSet<Product> Products => Set<Product>();
5.     protected override void OnModelCreating(ModelBuilder modelBuilder)
6.     {
7.         // HasIndex removed: Cosmos DB indexing is managed via the container's
8.         // indexing policy (Azure Portal / Bicep / Terraform), not EF Core.
9.         // In EF Core 9 HasIndex throws InvalidOperationException for Cosmos entities.
10. 
11.         modelBuilder.Entity<Product>().ToContainer("Products");
12. 
13.         // EF Core 9 changed the default discriminator property from "Discriminator"
14.         // to "$type". Our existing 500K documents use "Discriminator", and direct
15.         // SQL queries reference c.Discriminator — keep the old name.
16.         modelBuilder.Entity<Product>().HasDiscriminator<string>("Discriminator");
17. 
18.         // EF Core 9 changed id values from "EntityType|Key" (e.g. "Product|123")
19.         // to just the key value ("123"). Preserve the old compound format so
20.         // FindAsync and point-reads continue to work against existing documents.
21.         modelBuilder.Entity<Product>().HasRootDiscriminatorInJsonId(true);
22.     }
23. }
24. class Product { public int Id { get; set; } public string Sku { get; set; } }
